import { serveSnapshot, type AssetsBinding } from '../src/server/botPrerender';

// Every visitor gets the prerendered snapshot for the route when one exists; everything else
// (routes with no snapshot, assets, API calls) passes through to the existing app unchanged.
// Snapshots are generated by scripts/prerender.js and still load the app's JS bundle, so React
// hydrates on top of the static markup and the page stays fully interactive.
export const onRequest = async (context: {
  request: Request;
  env: { ASSETS: AssetsBinding };
  next: () => Promise<Response>;
}): Promise<Response> => {
  const snapshot = await serveSnapshot(context.request, context.env.ASSETS);
  return snapshot ?? context.next();
};
